query geoAccommodationLocation(
  $geoAccommodationLocationRequest: GeoAccommodationLocationRequest!
) {
  geoAccommodationLocation(
    geoAccommodationLocationRequest: $geoAccommodationLocationRequest
  ) {
    mainRegion {
      regionId
      name
      regionType
    }
    coordinates {
      latitude
      longitude
    }
    countryCode
    segments {
      regionId
      name
      regionType
    }
    imageUrl
  }
}
